                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_cutlass_ffi_bindings_fn_free_exportprogress(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_cutlass_ffi_bindings_fn_clone_exportprogress(handle, status)
        }
    }

    override fun `progress`(`done`: kotlin.ULong, `total`: kotlin.ULong): kotlin.Boolean {
            return FfiConverterBoolean.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_cutlass_ffi_bindings_fn_method_exportprogress_progress(
        it,
        
        FfiConverterULong.lower(`done`),
        FfiConverterULong.lower(`total`),_status)
}
    }
    )
    }
    

    

    


    
    
    /**
     * @suppress
     */
    companion object
    
