// Put the implementation in an object so we don't pollute the top-level namespace
internal object uniffiCallbackInterfaceExportProgress {
    internal object `progress`: UniffiCallbackInterfaceExportProgressMethod0 {
        override fun callback(`uniffiHandle`: Long,`done`: Long,`total`: Long,`uniffiOutReturn`: ByteByReference,uniffiCallStatus: UniffiRustCallStatus,) {
            val uniffiObj = FfiConverterTypeExportProgress.handleMap.get(uniffiHandle)
            val makeCall = { ->
                uniffiObj.`progress`(
                    FfiConverterULong.lift(`done`),
                    FfiConverterULong.lift(`total`),
                )
            }
            val writeReturn = { value: kotlin.Boolean -> uniffiOutReturn.setValue(FfiConverterBoolean.lower(value)) }
            uniffiTraitInterfaceCall(uniffiCallStatus, makeCall, writeReturn)
        }
    }

    internal object uniffiFree: UniffiCallbackInterfaceFree {
        override fun callback(handle: Long) {
            FfiConverterTypeExportProgress.handleMap.remove(handle)
        }
    }

    internal object uniffiClone: UniffiCallbackInterfaceClone {
        override fun callback(handle: Long): Long {
            return FfiConverterTypeExportProgress.handleMap.clone(handle)
        }
    }

    internal var vtable = UniffiVTableCallbackInterfaceExportProgress.UniffiByValue(
        uniffiFree,
        uniffiClone,
        `progress`,
    )

    // Registers the foreign callback with the Rust side.
    // This method is generated for each callback interface.
    internal fun register(lib: UniffiLib) {
        lib.uniffi_cutlass_ffi_bindings_fn_init_callback_vtable_exportprogress(vtable)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeExportProgress: FfiConverter<ExportProgress, Long> {
    internal val handleMap = UniffiHandleMap<ExportProgress>()

    override fun lower(value: ExportProgress): Long {
        if (value is ExportProgressImpl) {
             // Rust-implemented object.  Clone the handle and return it
            return value.uniffiCloneHandle()
         } else {
            // Kotlin object, generate a new vtable handle and return that.
            return handleMap.insert(value)
         }
    }

    override fun lift(value: Long): ExportProgress {
        if ((value and 1.toLong()) == 0.toLong()) {
            // Rust-generated handle, construct a new class that uses the handle to implement the
            // interface
            return ExportProgressImpl(UniffiWithHandle, value)
        } else {
            // Kotlin-generated handle, get the object from the handle map
            return handleMap.remove(value)
        }
    }

    override fun read(buf: ByteBuffer): ExportProgress {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: ExportProgress) = 8UL

    override fun write(value: ExportProgress, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



