/**
 * What fills the canvas around the main pictures.
 */
sealed class Background {
    
    /**
     * Clear: black shows.
     */
    object None : Background()
    
    
    /**
     * The project color, `#RRGGBB`.
     */
    data class Color(
        val `color`: kotlin.String) : Background()
        
    {
        

        companion object
    }
    
    /**
     * Every main picture over a blurred copy of itself.
     */
    data class Blur(
        val `blur`: kotlin.Double) : Background()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeBackground : FfiConverterRustBuffer<Background>{
    override fun read(buf: ByteBuffer): Background {
        return when(buf.getInt()) {
            1 -> Background.None
            2 -> Background.Color(
                FfiConverterString.read(buf),
                )
            3 -> Background.Blur(
                FfiConverterDouble.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Background): ULong = when(value) {
        is Background.None -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Background.Color -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`color`)
            )
        }
        is Background.Blur -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterDouble.allocationSize(value.`blur`)
            )
        }
    }

    override fun write(value: Background, buf: ByteBuffer) {
        when(value) {
            is Background.None -> {
                buf.putInt(1)
                Unit
            }
            is Background.Color -> {
                buf.putInt(2)
                FfiConverterString.write(value.`color`, buf)
                Unit
            }
            is Background.Blur -> {
                buf.putInt(3)
                FfiConverterDouble.write(value.`blur`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
 * Why a call left the project as it was.
 */
sealed class EditorException(message: String): kotlin.Exception(message) {
        
        class Failed(message: String) : EditorException(message)
        

